contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        address originalOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(caller != originalOwner, "caller must be a non-owner");

        bool reverted;
        c.transferOwnership(caller); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.owner() == originalOwner);
    }

    receive() external payable {}
}

