        c = new Owned();
    }

    function _run(address caller) internal {
        address originalOwner;
        try c.owner() returns (address __r) { originalOwner = __r; } catch { return; }
        vm.assume(caller != originalOwner);
        bool reverted;
        try c.transferOwnership(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }
